const NICHE_STATUS_META = {
  A: { key: "A", label: "空置 Available", color: SHEET.availInk, bg: SHEET.avail },
  S: { key: "S", label: "已售 Sold", color: SHEET.soldInk, bg: SHEET.sold },
  R: { key: "R", label: "保留 Reserved", color: SHEET.reservedInk, bg: SHEET.reserved },
  X: { key: "X", label: "分类格 · 状态待确认", color: SHEET.specialInk, bg: SHEET.special },
  U: { key: "U", label: "非售卖 Not for Sale", color: SHEET.notForSaleInk, bg: SHEET.notForSale },
};

/* ---------------------------- shared bits ------------------------------ */
function AlphaMark({ size = 20 }) {
  return (
    <div style={{ width: size, height: size, borderRadius: 6, background: COLOR.gold, color: "#141414", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT_DISPLAY, fontWeight: 700, fontSize: size * 0.6 }}>
      α
    </div>
  );
}
function Card({ children, style, onClick }) {
  return (
    <div onClick={onClick} className="rounded-2xl p-4" style={{ background: COLOR.panel, border: `1px solid ${COLOR.line}`, ...style }}>
      {children}
    </div>
  );
}
function TopBar({ title, onBack, right }) {
  return (
    <div className="sticky top-0 z-20 flex items-center justify-between px-4 py-3.5" style={{ background: COLOR.bg, borderBottom: `1px solid ${COLOR.line}` }}>
      <div className="flex items-center gap-2">
        {onBack && (
          <button onClick={onBack} className="p-1 -ml-1" style={{ color: COLOR.inkSoft }}>
            <ChevronLeft size={20} />
          </button>
        )}
        <span style={{ fontFamily: FONT_DISPLAY, color: COLOR.ink, fontSize: 17, fontWeight: 600 }}>{title}</span>
      </div>
      {right}
    </div>
  );
}
function TextInput(props) {
  return (
    <input {...props} className={"rounded-xl px-3.5 py-2.5 text-sm outline-none w-full " + (props.className || "")}
      style={{ background: COLOR.panel2, border: `1px solid ${COLOR.line}`, color: COLOR.ink, fontFamily: FONT_BODY, ...(props.style || {}) }} />
  );
}
function Select(props) {
  return (
    <select {...props} className={"rounded-xl px-3.5 py-2.5 text-sm outline-none w-full " + (props.className || "")}
      style={{ background: COLOR.panel2, border: `1px solid ${COLOR.line}`, color: COLOR.ink, fontFamily: FONT_BODY }}>
      {props.children}
    </select>
  );
}
function Btn({ children, onClick, variant = "primary", disabled, className = "", style }) {
  const styles = {
    primary: { background: COLOR.gold, color: "#161512" },
    ghost: { background: "transparent", color: COLOR.ink, border: `1px solid ${COLOR.line}` },
    danger: { background: "transparent", color: COLOR.red },
  };
  return (
    <button onClick={onClick} disabled={disabled} className={`rounded-xl px-4 py-2.5 text-sm flex items-center justify-center gap-1.5 ${className}`}
      style={{ fontFamily: FONT_BODY, fontWeight: 600, opacity: disabled ? 0.45 : 1, ...styles[variant], ...style }}>
      {children}
    </button>
  );
}
const STATUS_META = {
  available: { label: "AVAILABLE 空置", color: COLOR.green, bg: COLOR.greenBg, Icon: CheckCircle2 },
  sold: { label: "SOLD / NOT LISTED 已售或查无", color: COLOR.red, bg: COLOR.redBg, Icon: XCircle },
};
function StatusPill({ status }) {
  const m = STATUS_META[status] || STATUS_META.sold;
  const Icon = m.Icon;
  return (
    <span className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs" style={{ background: m.bg, color: m.color, fontFamily: FONT_BODY, fontWeight: 700, letterSpacing: 0.4 }}>
      <Icon size={13} /> {m.label}
    </span>
  );
}
// The sheets mark every column single or double, and that decides which price column
// applies -- so it is worth showing wherever a niche is named, not buried in the calculator.
function UnitPill({ unit }) {
  if (!unit) return null;
  const double = unit === "D";
  return (
    <span className="inline-flex items-center px-1.5 py-0.5 rounded ml-1.5 align-middle"
      style={{
        background: double ? "rgba(214,178,94,0.16)" : "rgba(255,255,255,0.07)",
        color: double ? COLOR.gold : COLOR.inkSoft,
        border: `1px solid ${double ? "rgba(214,178,94,0.4)" : COLOR.line}`,
        fontFamily: FONT_BODY, fontWeight: 700, fontSize: 10, letterSpacing: 0.2,
      }}>
      {double ? "D 双人" : "S 单人"}
    </span>
  );
}
function Row({ label, value, bold, accent }) {
  return (
    <div className="flex items-center justify-between py-1.5" style={{ borderTop: `1px solid ${COLOR.line}` }}>
      <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 12.5 }}>{label}</span>
      <span style={{ color: accent ? COLOR.gold : COLOR.ink, fontFamily: FONT_BODY, fontWeight: bold ? 700 : 500, fontSize: 13, fontVariantNumeric: "tabular-nums" }}>{value}</span>
    </div>
  );
}

/* ---------------------------- floor plan schematic ------------------------------ */
// Based on the actual Jiangnan Villa floor plans (Block G / Block K on file): each Hall is a
// U-shaped enclosure open toward the South (facing the water pond). "R" (Right) is the WEST leg,
// "L" (Left) is the EAST leg — named from the altar/deity's perspective looking outward, not the
// visitor's. "F" (Frontage) is the North wall. Halls run West→East as Hall 3, Hall 2, Hall 1.
// Our data can't always tell R from L individually (they share one price), so for "Right/Left"
// we highlight both side legs.
//
// Block L is laid out differently (confirmed against the Block L ground floor plan): only
// LC1 / LB1 / LA1 are Frontage (the outer row facing the main aisle). Only LB2 / LB3 (Hall B's
// own two side columns) are split Left/Right — LB3 sits on the west side next to Hall C, LB2 on
// the east side next to Hall A. Every other column (A2/A3/A6-12, C2/C3/C6-12) is just an interior
// pillar with no Frontage/Left/Right distinction at all.
function HallDiagram({ highlightF, highlightR, highlightL, footerLabel }) {
  const dim = (on) => (on ? COLOR.gold : COLOR.line);
  const dimFill = (on) => (on ? COLOR.goldSoft : "transparent");
  return (
    <div className="rounded-xl p-3" style={{ background: COLOR.panel2, border: `1px solid ${COLOR.line}` }}>
      <svg viewBox="0 0 160 110" width="100%" height="120">
        {/* frontage - top wall */}
        <rect x="20" y="8" width="120" height="14" rx="2" stroke={dim(highlightF)} strokeWidth="2" fill={dimFill(highlightF)} />
        <text x="80" y="18" textAnchor="middle" fontSize="9" fill={highlightF ? COLOR.gold : COLOR.inkSoft} fontFamily={FONT_BODY}>F 正面 Frontage</text>
        {/* right leg = "R" = WEST (screen-left) */}
        <rect x="20" y="22" width="14" height="72" rx="2" stroke={dim(highlightR)} strokeWidth="2" fill={dimFill(highlightR)} />
        <text x="27" y="60" textAnchor="middle" fontSize="9" fill={highlightR ? COLOR.gold : COLOR.inkSoft} fontFamily={FONT_BODY} transform="rotate(-90 27 60)">R 右</text>
        {/* left leg = "L" = EAST (screen-right) */}
        <rect x="126" y="22" width="14" height="72" rx="2" stroke={dim(highlightL)} strokeWidth="2" fill={dimFill(highlightL)} />
        <text x="133" y="60" textAnchor="middle" fontSize="9" fill={highlightL ? COLOR.gold : COLOR.inkSoft} fontFamily={FONT_BODY} transform="rotate(-90 133 60)">L 左</text>
        {/* arrow pointing at whichever is selected */}
        {highlightF && <polygon points="80,28 75,36 85,36" fill={COLOR.gold} />}
        {highlightR && <polygon points="36,58 44,53 44,63" fill={COLOR.gold} />}
        {highlightL && <polygon points="124,58 116,53 116,63" fill={COLOR.gold} />}
        {/* compass */}
        <text x="80" y="106" textAnchor="middle" fontSize="8" fill={COLOR.inkSoft} fontFamily={FONT_BODY}>南 South · 面向水池 facing water pond</text>
        <text x="80" y="4" textAnchor="middle" fontSize="7" fill={COLOR.inkSoft} fontFamily={FONT_BODY}>北 North</text>
      </svg>
      <div className="text-center text-[10px] mt-1" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        {footerLabel}
      </div>
    </div>
  );
}

const BLOCK_L_FRONTAGE_HALLS = ["A1", "C1", "B1"];
const BLOCK_L_RIGHT_HALL = "B3"; // west leg, next to Hall C
const BLOCK_L_LEFT_HALL = "B2"; // east leg, next to Hall A

function MiniFloorPlan({ block, side, hallcode }) {
  if (block === "L") {
    if (BLOCK_L_FRONTAGE_HALLS.includes(hallcode)) {
      return <HallDiagram highlightF footerLabel={`L${hallcode} · 正面 Frontage(临主通道)`} />;
    }
    if (hallcode === BLOCK_L_RIGHT_HALL) {
      return <HallDiagram highlightR footerLabel="LB3 · Right 右(Hall B 靠近 Hall C 那一侧)" />;
    }
    if (hallcode === BLOCK_L_LEFT_HALL) {
      return <HallDiagram highlightL footerLabel="LB2 · Left 左(Hall B 靠近 Hall A 那一侧)" />;
    }
    return (
      <div className="rounded-xl p-3 flex items-center gap-2" style={{ background: COLOR.panel2, border: `1px solid ${COLOR.line}` }}>
        <Info size={14} color={COLOR.inkSoft} />
        <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 11.5 }}>
          {hallcode ? `L${hallcode}` : "此福位"} · 内部柱位,无方位区分(不是 Frontage,也不分 Left/Right)
        </span>
      </div>
    );
  }

  if (side === "SEC" || side === "S") {
    return (
      <div className="rounded-xl p-3 flex items-center gap-2" style={{ background: COLOR.panel2, border: `1px solid ${COLOR.line}` }}>
        <Info size={14} color={COLOR.inkSoft} />
        <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 11.5 }}>
          此 Block 的分区方式跟 Hall/R/F/L 不同,实际方位请跟主管确认
        </span>
      </div>
    );
  }
  const highlightR = side === "RL";
  const highlightL = side === "RL";
  const highlightF = side === "F";
  return (
    <HallDiagram
      highlightF={highlightF}
      highlightR={highlightR}
      highlightL={highlightL}
      footerLabel={`${hallcode ? `Hall ${hallcode}` : ""} · R/L 按公司命名习惯(从神位往外看),不是访客自己的左右手`}
    />
  );
}

/* ============================ SEARCH / FIND LOT =================================== */
const BLOCKS = ["A", "B", "C", "D", "E", "F", "G", "K", "L", "M", "N", "P"];

const BURIAL_STATUS_ZONE_KEYS = Object.keys(BURIAL_STATUS);

// Burial plots are coded <zone>-<row>-<plot> (B-1A-18, CA-1-208, DA-13-118), so the search
// box takes the same shape the sheets print. Source order is sheet order -- zones as the
// plan pages run, rows top-to-bottom, plots left-to-right -- so results are never re-sorted.
const [BURIAL_AVAIL, BURIAL_ROWS] = (() => {
  const avail = [];
  const rows = {}; // zone -> { row: {total, avail} }
  for (const zone of BURIAL_STATUS_ZONE_KEYS) {
    rows[zone] = {};
    for (const zrow of BURIAL_STATUS[zone]) {
      let total = 0;
      let free = 0;
      for (const cell of zrow.cells) {
        total += 1;
        if (cell.s !== "A") continue;
        free += 1;
        // The plot number is the last segment; searching "208" should mean plot 208, not
        // stumble over a row that happens to contain those digits.
        const plot = cell.c.split("-").slice(2).join("-");
        avail.push({
          zone, row: zrow.row, code: cell.c,
          plot, plotNorm: plot.replace(/-/g, "").toUpperCase(),
        });
      }
      rows[zone][zrow.row] = { total, avail: free };
    }
  }
  return [avail, rows];
})();

// The zone written in a code is not always the zone key: Zone DB's row 13 is a separate
// product, coded DBS- and kept as its own zone in the app.
const BURIAL_ZONE_ALIASES = { DBS: "DB13", DB13: "DB13" };
// Longest first, so "DBS" and "DB13" win over the "DB" that starts them.
const BURIAL_ZONE_TOKENS = ["DB13", "DBS", "CA", "CB", "DA", "DB", "IZ", "B"];

// "B", "B-1A", "B-1A-18", "B1A", "DA-13", "1A", "208" all have to land somewhere sensible.
// The zone is only peeled off the front when what follows actually reads as a row (or the
// query is separated, or nothing follows) -- otherwise "B8" would lose its B and turn into
// a search for plot 8, which matches nearly every plot on the site.
function parseBurialQuery(raw) {
  const s = raw.trim().toUpperCase().replace(/\s+/g, "");
  if (!s) return null;

  const hasSep = /[-·.]/.test(s);
  let zone = "";
  let rest = s;
  for (const token of BURIAL_ZONE_TOKENS) {
    if (!s.startsWith(token)) continue;
    const tail = s.slice(token.length).replace(/^[-·.]/, "");
    const key = BURIAL_ZONE_ALIASES[token] || token;
    if (!BURIAL_ROWS[key]) continue;
    if (tail === "" || hasSep || BURIAL_ROWS[key][tail.split(/[-·.]/)[0]]) {
      zone = key;
      rest = tail;
      break;
    }
  }

  if (!rest) return { zone, row: "", plot: "" };

  const parts = rest.split(/[-·.]/).filter(Boolean);
  const rowExists = (r) => (zone ? !!BURIAL_ROWS[zone][r]
    : BURIAL_STATUS_ZONE_KEYS.some((z) => BURIAL_ROWS[z][r]));
  if (rowExists(parts[0])) {
    return { zone, row: parts[0], plot: parts.slice(1).join("") };
  }
  return { zone, row: "", plot: parts.join("") };
}

function BurialSearchView({ go }) {
  const [q, setQ] = useState("");
  const [zoneFilter, setZoneFilter] = useState("");

  const search = useMemo(() => {
    const parsed = parseBurialQuery(q);
    if (!parsed || (!parsed.zone && !parsed.row && !parsed.plot)) return null;

    const matched = BURIAL_AVAIL.filter((r) => {
      if (zoneFilter && r.zone !== zoneFilter) return false;
      if (parsed.zone && r.zone !== parsed.zone) return false;
      if (parsed.row && r.row !== parsed.row) return false;
      if (parsed.plot && !r.plotNorm.includes(parsed.plot)) return false;
      return true;
    });

    // Same distinction the niche search makes: a row that is real but fully taken is a
    // different answer from a row that isn't in the data, and the first is the useful one.
    let soldOutRow = null;
    if (!matched.length && parsed.row && !parsed.plot) {
      const zones = (parsed.zone ? [parsed.zone] : BURIAL_STATUS_ZONE_KEYS)
        .filter((z) => (!zoneFilter || z === zoneFilter) && BURIAL_ROWS[z][parsed.row]);
      if (zones.length) {
        soldOutRow = {
          row: parsed.row,
          zones,
          total: zones.reduce((a, z) => a + BURIAL_ROWS[z][parsed.row].total, 0),
        };
      }
    }

    const shown = matched.slice(0, RESULT_CAP);
    const groups = [];
    for (const r of shown) {
      const last = groups[groups.length - 1];
      if (last && last.zone === r.zone && last.row === r.row) last.items.push(r);
      else groups.push({ zone: r.zone, row: r.row, items: [r] });
    }
    return { parsed, total: matched.length, groups, soldOutRow };
  }, [q, zoneFilter]);

  const shownCount = search ? search.groups.reduce((a, g) => a + g.items.length, 0) : 0;
  const zoneLabel = (z) => BURIAL_ZONES.find((x) => x.key === z)?.label || z;

  return (
    <div>
      <div className="flex items-start gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, lineHeight: 1.6 }}>
        <Info size={13} className="flex-shrink-0" style={{ marginTop: 2 }} />
        <span>
          只列空置(available)位子,截至 {BURIAL_STATUS_UPDATED}。
          打 <b style={{ color: COLOR.ink }}>B</b> 是整个 Zone,
          <b style={{ color: COLOR.ink }}>B-1A</b> 是那一行,
          <b style={{ color: COLOR.ink }}>B-1A-18</b> 是单一位子,
          只打 <b style={{ color: COLOR.ink }}>208</b> 就在全部 Zone 里找这个位子号。
        </span>
      </div>

      <div className="flex gap-2 mb-3">
        <TextInput placeholder="Zone／行／位子号 e.g. B / B-1A / B-1A-18 / 208" value={q} onChange={(e) => setQ(e.target.value)} />
        <Select value={zoneFilter} onChange={(e) => setZoneFilter(e.target.value)} style={{ width: 120 }}>
          <option value="">全部 Zone</option>
          {BURIAL_STATUS_ZONE_KEYS.map((zk) => <option key={zk} value={zk}>{zk}</option>)}
        </Select>
      </div>

      {search && search.total > 0 && (
        <div className="mb-3" style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 13, fontWeight: 700 }}>
          找到 {search.total} 个空置
          {search.total > shownCount && (
            <span style={{ color: COLOR.inkSoft, fontWeight: 500 }}> · 只显示前 {shownCount} 个,再打细一点就能缩小范围</span>
          )}
        </div>
      )}

      {search && search.total === 0 && (
        <p style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 13, lineHeight: 1.7 }}>
          {search.soldOutRow ? (
            <>
              第 <b style={{ color: COLOR.ink }}>{search.soldOutRow.row}</b> 行
              ({search.soldOutRow.zones.join("／")})在资料库里有 {search.soldOutRow.total} 个位子,
              但目前<b style={{ color: COLOR.ink }}>没有一个是空置的</b>(全部已售/保留)。
            </>
          ) : (
            <>没有找到空置位子 — 可能已售出,或 Zone／编号不在资料库里。请跟主管确认。</>
          )}
        </p>
      )}

      <div className="space-y-4">
        {(search ? search.groups : []).map((g) => (
          <div key={`${g.zone}-${g.row}`}>
            <div className="flex items-baseline justify-between gap-2 mb-1.5 px-0.5">
              <span style={{ color: COLOR.ink, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 13, minWidth: 0 }}>
                {zoneLabel(g.zone)} · 第 {g.row} 行
              </span>
              <span className="flex-shrink-0" style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 11, fontWeight: 700 }}>
                空 {g.items.length}
                <span style={{ color: COLOR.inkSoft, fontWeight: 500 }}> / {BURIAL_ROWS[g.zone][g.row].total}</span>
              </span>
            </div>
            <div className="space-y-2">
              {g.items.map((r) => (
                <Card key={r.code} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div className="flex-1" onClick={() => go("calculator", { zoneKey: r.zone, code: r.code }, null, "burial")} style={{ cursor: "pointer" }}>
                    <span style={{ fontFamily: FONT_DISPLAY, color: COLOR.ink, fontSize: 15, fontWeight: 700 }}>{r.code}</span>
                    <div style={{ color: COLOR.inkSoft, fontSize: 12, fontFamily: FONT_BODY, marginTop: 2 }}>
                      {zoneLabel(r.zone)} · 第 {r.row} 行 · 位子 {r.plot}
                    </div>
                  </div>
                  <StatusPill status="available" />
                </Card>
              ))}
            </div>
          </div>
        ))}
      </div>

      {search && search.total > 0 && (
        <p className="mt-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
          点卡片直接带入计算器算这个位子的价钱
        </p>
      )}
    </div>
  );
}

