const NICHE_STATUS_BLOCK_KEYS = Object.keys(NICHE_STATUS);

// Each hall is physically made of separate walls, and the company's own floor plans
// draw them that way: the Frontage runs along the back, with the Right and Left wings
// coming off it, enclosing the hall. (Block L is different — each "section" is one
// free-standing wall, so it renders as a single face.) Showing them as one continuous
// strip of codes hides where one wall ends and the next begins, so each face gets its
// own 2D grid: levels down the side, positions across, exactly like the paper plan.
const WING_META = {
  R: { label: "R · 右 Right Wing", hint: "西侧" },
  F: { label: "F · 正面 Frontage", hint: "背墙" },
  L: { label: "L · 左 Left Wing", hint: "东侧" },
  S: { label: "S · 侧面 Side", hint: "N 座专用" },
  SEC: { label: "整面 Section", hint: "" },
};
// R and L share a price tier, so the wall a niche sits on maps to a coarser pricing side.
const WING_TO_SIDE = { R: "RL", L: "RL", F: "F", S: "S", SEC: "SEC" };

// Agents read the printed plans by wall -- "A1L" is Block A, Hall 1, Left wing -- so the
// search box has to accept that shorthand, not just a bare code. AVAIL_RAW can't answer a
// wall query: it collapses Right and Left into the single pricing side "RL" and loses which
// wall a niche is actually on. NICHE_STATUS keeps it, and the two are generated from the
// same sheet and agree exactly, so the searchable index is built from NICHE_STATUS instead.
// Source order is sheet order (faces as drawn, levels top-down, cells left to right), so
// results are never re-sorted -- iterating the index already lists them the way the paper does.
const [NICHE_AVAIL, NICHE_WALLS] = (() => {
  const rows = [];
  const walls = {}; // wall code -> [{ block, hallcode, wing, total, avail }]
  for (const block of Object.keys(NICHE_STATUS)) {
    for (const hallcode of Object.keys(NICHE_STATUS[block])) {
      for (const face of NICHE_STATUS[block][hallcode]) {
        const wing = face.w;
        // Block L's sections are single free-standing walls with no wing letter, so the
        // wall code is just the section code ("A6"), matching how the sheet labels them.
        const wall = hallcode + (wing === "SEC" ? "" : wing);
        let total = 0;
        let avail = 0;
        for (const row of face.rows) {
          for (const cell of row.cells) {
            if (!cell) continue; // deliberate blank slot in the wall, not a niche
            total += 1;
            if (cell.s !== "A") continue;
            avail += 1;
            rows.push({
              block, hallcode, wing, wall,
              side: WING_TO_SIDE[wing] || wing,
              level: row.level,
              code: cell.c,
              unit: cell.u || "",          // "D" double / "S" single, as the sheet marks it
              codeNorm: cell.c.replace(/-/g, "").toUpperCase(),
            });
          }
        }
        (walls[wall] = walls[wall] || []).push({ block, hallcode, wing, total, avail });
      }
    }
  }
  return [rows, walls];
})();

// One box has to take every shape an agent might type: a wall ("A1L"), a whole hall ("A1"),
// a whole block ("A"), a bare code ("1032"), or any of those with a code after it
// ("A1L-10-32"). Hyphens are dropped on both sides before comparing because the same idea
// is printed two ways depending on the block -- Block A writes 1032, Block F writes 09-138.
//
// The block may also be written in front ("L-A6"). That matters most for Block L, whose
// sections are named A1..A12, B1..B3, C1..C12 with no "L" anywhere in them -- so the
// natural thing to type is the block plus the section -- and whose A1/A2/A3/B1..B3/C1..C7
// collide by name with real halls in Blocks A, B and C. Without the prefix, "A1" can only
// answer with both blocks at once.
//
// A block prefix is two letters then a digit ("LA6"); a wall is one letter, a digit, then
// the wing ("A1L"). The second character tells them apart, so neither reading is ambiguous.
function parseNicheQuery(raw) {
  const s = raw.trim().toUpperCase().replace(/\s+/g, "");
  if (!s) return null;

  let block = "";
  let rest = s;
  const prefixed = s.match(/^([A-Z])[-·.]?(?=[A-Z]\d)/);
  if (prefixed) {
    block = prefixed[1];
    rest = s.slice(prefixed[0].length);
  }

  const m = rest.match(/^([A-Z])(\d{1,2})([RFLS])?[-·.]?(.*)$/);
  if (m) {
    const [, letter, num, wing, tail] = m;
    return { block, hallcode: letter + num, wing: wing || "", code: tail.replace(/-/g, "") };
  }
  if (/^[A-Z]$/.test(s)) return { block: s, hallcode: "", wing: "", code: "" };
  return { block: "", hallcode: "", wing: "", code: s.replace(/-/g, "") };
}

// A whole block can be thousands of rows; the true count is still reported above the list.
const RESULT_CAP = 200;

function FaceGrid({ face, block, hallcode, qLower, go }) {
  const meta = WING_META[face.w] || { label: face.w, hint: "" };
  const side = WING_TO_SIDE[face.w] || face.w;
  const filterActive = qLower.length > 0;

  const counts = useMemo(() => {
    const c = { total: 0 };
    face.rows.forEach((r) => r.cells.forEach((cell) => {
      if (!cell) return; // blank slot in the wall, not a niche
      c[cell.s] = (c[cell.s] || 0) + 1;
      c.total += 1;
    }));
    return c;
  }, [face]);

  // One D/S per column. It is a column property on the sheets, but a column can have a
  // blank slot in some rows, so take the first row that actually has a cell there.
  const unitHeader = useMemo(() => {
    const width = Math.max(...face.rows.map((r) => r.cells.length), 0);
    const out = Array(width).fill("");
    for (let col = 0; col < width; col += 1) {
      for (const r of face.rows) {
        const cell = r.cells[col];
        if (cell && cell.u) { out[col] = cell.u; break; }
      }
    }
    return out.some(Boolean) ? out : null;
  }, [face]);

  return (
    <div className="mb-3">
      <div className="flex items-baseline justify-between gap-2 mb-1.5 px-0.5">
        <div className="flex items-baseline gap-2" style={{ minWidth: 0 }}>
          <span style={{ color: COLOR.ink, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12.5 }}>
            {hallcode}{face.w === "SEC" ? "" : face.w}
          </span>
          <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 11 }}>
            {meta.label}{meta.hint && ` · ${meta.hint}`}
          </span>
        </div>
        <span className="flex-shrink-0" style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 11, fontWeight: 700 }}>
          空 {counts.A || 0}
          <span style={{ color: COLOR.inkSoft, fontWeight: 500 }}> / {counts.total}</span>
        </span>
      </div>

      <div className="rounded-xl" style={{ border: `1px solid ${COLOR.line}`, overflowX: "auto" }}>
        <div style={{ width: "max-content" }}>
          {/* The sheets head every wall with a D/S row -- one per column, since single and
              double is a property of the whole column. Same place here, so the screen reads
              like the paper an agent already knows. */}
          {unitHeader && (
            <div className="flex items-stretch">
              <div className="flex items-center justify-center flex-shrink-0"
                style={{ width: 30, background: COLOR.panel2, color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 9, fontWeight: 700, position: "sticky", left: 0, zIndex: 1 }}>
                单双
              </div>
              {unitHeader.map((u, col) => (
                <div key={`u-${col}`} className="flex items-center justify-center flex-shrink-0"
                  title={u === "D" ? "这一栏是双人位 Double" : u === "S" ? "这一栏是单人位 Single" : ""}
                  style={{
                    width: 52, padding: "3px 2px", background: COLOR.panel2,
                    color: u === "D" ? COLOR.gold : u === "S" ? COLOR.ink : COLOR.inkSoft,
                    fontFamily: FONT_BODY, fontSize: 10.5, fontWeight: 800,
                    borderLeft: `1px solid ${COLOR.line}`,
                  }}>
                  {u || ""}
                </div>
              ))}
            </div>
          )}
          {face.rows.map((r) => (
            <div key={r.level} className="flex items-stretch" style={{ borderTop: `1px solid ${COLOR.line}` }}>
              <div className="flex items-center justify-center flex-shrink-0"
                style={{ width: 30, background: COLOR.panel2, color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 10.5, fontWeight: 700, position: "sticky", left: 0, zIndex: 1 }}>
                {r.level}
              </div>
              {r.cells.map((cell, col) => {
                // A null slot is a real blank in the wall, not padding: the sheets leave a
                // gap so the two halves of a wall stay aligned. Keep the space (and skip the
                // cell border) so every column below it stays where the paper puts it.
                if (!cell) {
                  // Painting the gap in the page colour reads as a hole punched in the wall.
                  // Hatch it in the grid's own neutral so it looks like what it is: a slot the
                  // sheet leaves empty to keep the two halves aligned.
                  return (
                    <div key={`gap-${col}`} className="flex-shrink-0"
                      title="这里图纸上就没有格子(用来对齐两边的空位)"
                      style={{
                        width: 52,
                        borderLeft: `1px solid ${COLOR.line}`,
                        background: `repeating-linear-gradient(45deg, #3A3B40, #3A3B40 3px, ${COLOR.panel2} 3px, ${COLOR.panel2} 7px)`,
                      }} />
                  );
                }
                const m = NICHE_STATUS_META[cell.s] || NICHE_STATUS_META.X;
                const dim = filterActive && !cell.c.toLowerCase().includes(qLower);
                const cellStyle = {
                  width: 52, padding: "6px 2px", background: m.bg, color: m.color,
                  fontFamily: FONT_BODY, fontSize: 9.5, fontWeight: 700,
                  borderLeft: `1px solid ${COLOR.line}`, opacity: dim ? 0.2 : 1,
                  position: "relative",
                };
                // Single/double is shown once per column in the header row above, exactly
                // where the sheets put it, so the code stays the only thing inside the cell.
                const unitWord = cell.u === "D" ? "双人位 Double" : cell.u === "S" ? "单人位 Single" : "";
                if (cell.s === "A") {
                  return (
                    <button key={cell.c} title={`${cell.c} · ${meta.label}${unitWord ? " · " + unitWord : ""} · 点击去计算器`}
                      onClick={() => go("calculator", { block, hallcode, side, level: r.level, code: cell.c, unit: cell.u || "" }, null, "niche")}
                      className="flex items-center justify-center flex-shrink-0" style={{ ...cellStyle, cursor: "pointer" }}>
                      {cell.c}
                    </button>
                  );
                }
                return (
                  <div key={cell.c} title={`${cell.c} · ${m.label}${unitWord ? " · " + unitWord : ""}`} className="flex items-center justify-center flex-shrink-0" style={cellStyle}>
                    {cell.c}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function NicheAvailabilityView({ go }) {
  const [block, setBlock] = useState(NICHE_STATUS_BLOCK_KEYS[0]);
  const [hallcode, setHallcode] = useState(Object.keys(NICHE_STATUS[NICHE_STATUS_BLOCK_KEYS[0]])[0]);
  const [q, setQ] = useState("");

  const hallKeys = Object.keys(NICHE_STATUS[block] || {});
  const activeHallcode = hallKeys.includes(hallcode) ? hallcode : hallKeys[0];
  const faces = (NICHE_STATUS[block] && NICHE_STATUS[block][activeHallcode]) || [];
  const qLower = q.trim().toLowerCase();

  const counts = useMemo(() => {
    const c = { A: 0, S: 0, R: 0, X: 0, U: 0 };
    faces.forEach((f) => f.rows.forEach((r) => r.cells.forEach((cell) => {
      if (cell) c[cell.s] = (c[cell.s] || 0) + 1;
    })));
    return c;
  }, [faces]);

  const handleBlockChange = (key) => {
    setBlock(key);
    setHallcode(Object.keys(NICHE_STATUS[key] || {})[0]);
  };

  return (
    <div>
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 位子图截至 {NICHE_STATUS_UPDATED} — 每天都有成交,只作参考,下单前务必核实
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Block</div>
          <Select value={block} onChange={(e) => handleBlockChange(e.target.value)}>
            {NICHE_STATUS_BLOCK_KEYS.map((b) => <option key={b} value={b}>{b} 座</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>
            {block === "L" ? "Section 区段" : "Hall"}
          </div>
          <Select value={activeHallcode} onChange={(e) => setHallcode(e.target.value)}>
            {hallKeys.map((h) => <option key={h} value={h}>{h}</option>)}
          </Select>
        </div>
      </div>

      <TextInput placeholder="过滤编号 e.g. 1032, 09-18" value={q} onChange={(e) => setQ(e.target.value)} className="mb-3" />

      <div className="flex gap-2 mb-4 flex-wrap">
        {Object.values(NICHE_STATUS_META).map((m) => (
          <span key={m.key} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px]" style={{ background: m.bg, color: m.color, fontFamily: FONT_BODY, fontWeight: 700 }}>
            {m.label} · {counts[m.key] || 0}
          </span>
        ))}
      </div>

      {faces.map((face) => (
        <FaceGrid key={face.w} face={face} block={block} hallcode={activeHallcode} qLower={qLower} go={go} />
      ))}

      <div className="mt-1 text-[11px]" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, lineHeight: 1.7 }}>
        每一面墙分开显示,跟公司平面图一样:左边是层数(10 在上、1 在下),横向是这面墙由左到右的位置。
        点空置格子直接带去计算器算这一格的价钱。「分类格」「非售卖」是另一种颜色标记盖住了空/售状态,遇到要另外确认。
        <br />
        最上面那一行的 <b style={{ color: COLOR.ink }}>D</b> = 双人位 Double、
        <b style={{ color: COLOR.ink }}>S</b> = 单人位 Single —— 跟图纸一样一栏一个(整栏同一种)。
        点进计算器会自动帮你选好,不用再猜。斜纹格是图纸上本来就没有的空位,用来对齐两边,不是漏掉。
      </div>
    </div>
  );
}

function SearchScreen({ go, prefill }) {
  const [plotType, setPlotType] = useState(prefill?.plotType || "niche");
  const [nicheView, setNicheView] = useState("search"); // "search" | "grid"
  const [burialView, setBurialView] = useState("search"); // "search" | "grid"
  const [q, setQ] = useState(prefill?.q || "");
  const [blockFilter, setBlockFilter] = useState("");
  const [selected, setSelected] = useState([]); // multi-select for combined quotation

  // Arriving from the park guide ("show me Block A's free niches"). The nonce changes on
  // every jump, so tapping the same block twice re-runs it instead of doing nothing.
  useEffect(() => {
    if (!prefill) return;
    setPlotType(prefill.plotType || "niche");
    if (prefill.plotType === "burial") setBurialView("search"); else setNicheView("search");
    setQ(prefill.q || "");
    setBlockFilter("");
    setSelected([]);
  }, [prefill?.n]);

  const search = useMemo(() => {
    const parsed = parseNicheQuery(q);
    if (!parsed || (!parsed.block && !parsed.hallcode && !parsed.code)) return null;

    const matched = NICHE_AVAIL.filter((r) => {
      if (blockFilter && r.block !== blockFilter) return false;
      if (parsed.block && r.block !== parsed.block) return false;
      if (parsed.hallcode && r.hallcode !== parsed.hallcode) return false;
      if (parsed.wing && r.wing !== parsed.wing) return false;
      if (parsed.code && !r.codeNorm.includes(parsed.code)) return false;
      return true;
    });

    // An empty list can mean two very different things -- the wall isn't in the data, or the
    // wall is real and every niche on it is taken. The second is the answer an agent needs,
    // so look the wall up separately instead of showing one vague "not found" for both.
    let soldOutWall = null;
    if (!matched.length && parsed.hallcode && !parsed.code) {
      const wall = parsed.hallcode + parsed.wing;
      const entries = (NICHE_WALLS[wall] || []).filter(
        (e) => (!blockFilter || e.block === blockFilter) && (!parsed.block || e.block === parsed.block));
      if (entries.length) soldOutWall = { wall, total: entries.reduce((a, e) => a + e.total, 0) };
    }

    // The index is in sheet order, so walls are already contiguous -- group by walking it.
    const shown = matched.slice(0, RESULT_CAP);
    const groups = [];
    for (const r of shown) {
      const last = groups[groups.length - 1];
      if (last && last.block === r.block && last.wall === r.wall) last.items.push(r);
      else groups.push({ block: r.block, wall: r.wall, wing: r.wing, items: [r] });
    }
    return { parsed, total: matched.length, groups, soldOutWall };
  }, [q, blockFilter]);

  const results = search ? search.groups.flatMap((g) => g.items) : [];

  const keyOf = (r) => `${r.block}-${r.hallcode}-${r.wing || r.side}-${r.level}-${r.code}`;
  const isSelected = (r) => selected.some((s) => keyOf(s) === keyOf(r));
  const toggleSelect = (r) => {
    setSelected((prev) => (isSelected(r) ? prev.filter((s) => keyOf(s) !== keyOf(r)) : [...prev, r]));
  };

  const typeToggle = (
    <div className="flex gap-2 mb-3">
      <button onClick={() => setPlotType("niche")} className="flex-1 rounded-xl px-3 py-2 text-sm"
        style={{ background: plotType === "niche" ? COLOR.gold : COLOR.panel2, color: plotType === "niche" ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
        骨灰位 Niche
      </button>
      <button onClick={() => setPlotType("burial")} className="flex-1 rounded-xl px-3 py-2 text-sm"
        style={{ background: plotType === "burial" ? COLOR.gold : COLOR.panel2, color: plotType === "burial" ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
        土葬 Burial Plot
      </button>
    </div>
  );

  const viewToggle = (view, setView) => (
    <div className="flex gap-2 mb-3">
      <button onClick={() => setView("search")} className="flex-1 rounded-xl px-3 py-2 text-sm"
        style={{ background: view === "search" ? COLOR.panel2 : "transparent", color: view === "search" ? COLOR.ink : COLOR.inkSoft, border: `1px solid ${COLOR.line}`, fontFamily: FONT_BODY, fontWeight: 600 }}>
        编号搜索 Search
      </button>
      <button onClick={() => setView("grid")} className="flex-1 rounded-xl px-3 py-2 text-sm"
        style={{ background: view === "grid" ? COLOR.panel2 : "transparent", color: view === "grid" ? COLOR.ink : COLOR.inkSoft, border: `1px solid ${COLOR.line}`, fontFamily: FONT_BODY, fontWeight: 600 }}>
        格子图 Browse Grid
      </button>
    </div>
  );

  if (plotType === "burial") {
    return (
      <div className="px-4 pt-4 pb-28">
        {typeToggle}
        {viewToggle(burialView, setBurialView)}
        {burialView === "grid"
          ? <BurialAvailabilityView go={go} />
          : <BurialSearchView go={go} />}
      </div>
    );
  }

  const nicheViewToggle = viewToggle(nicheView, setNicheView);

  if (nicheView === "grid") {
    return (
      <div className="px-4 pt-4 pb-28">
        {typeToggle}
        {nicheViewToggle}
        <NicheAvailabilityView go={go} />
      </div>
    );
  }

  return (
    <div className="px-4 pt-4 pb-28">
      {typeToggle}
      {nicheViewToggle}
      <div className="flex items-start gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, lineHeight: 1.6 }}>
        <Info size={13} className="flex-shrink-0" style={{ marginTop: 2 }} />
        <span>
          只列空置(available)福位 — 已售的不会出现在这里。
          可以整面墙查:打 <b style={{ color: COLOR.ink }}>A1L</b> 就列出 A1 左面墙全部空置的,
          打 <b style={{ color: COLOR.ink }}>A1</b> 是整个 Hall,
          <b style={{ color: COLOR.ink }}>A1L-1032</b> 或 <b style={{ color: COLOR.ink }}>1032</b> 是查单一编号。
          <br />
          L 座的区段没有墙面字母(叫 A1、A6、C10…),而且 A1/B1/C1 这些跟 A/B/C 座撞名 —
          前面加座别就好:<b style={{ color: COLOR.ink }}>L-A6</b> 或 <b style={{ color: COLOR.ink }}>LA6</b>。
        </span>
      </div>
      <div className="flex gap-2 mb-3">
        <TextInput placeholder="墙面或编号 e.g. A1L / A1 / A1L-1032 / 1032" value={q} onChange={(e) => setQ(e.target.value)} />
        <Select value={blockFilter} onChange={(e) => setBlockFilter(e.target.value)} style={{ width: 110 }}>
          <option value="">全部 Block</option>
          {BLOCKS.map((b) => <option key={b} value={b}>{b} 座</option>)}
        </Select>
      </div>

      {search && search.total > 0 && (
        <div className="mb-3">
          <div style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 13, fontWeight: 700 }}>
            找到 {search.total} 个空置
            {search.total > results.length && (
              <span style={{ color: COLOR.inkSoft, fontWeight: 500 }}> · 只显示前 {results.length} 个,再打细一点就能缩小范围</span>
            )}
          </div>
          <div className="flex items-center gap-1.5 mt-1 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
            <Info size={13} /> 点卡片右边的圆圈可以多选,一次过生成组合报价单
          </div>
        </div>
      )}

      {search && search.total === 0 && (
        <p style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 13, lineHeight: 1.7 }}>
          {search.soldOutWall ? (
            <>
              <b style={{ color: COLOR.ink }}>{search.soldOutWall.wall}</b> 这面墙在资料库里有
              {search.soldOutWall.total} 格,但目前<b style={{ color: COLOR.ink }}>没有一格是空置的</b>(全部已售/保留)。
            </>
          ) : (
            <>没有找到空置福位 — 可能已售出,或编号/墙面不在资料库里。请跟主管确认。</>
          )}
        </p>
      )}

      <div className="space-y-4">
        {(search ? search.groups : []).map((g) => (
          <div key={`${g.block}-${g.wall}`}>
            <div className="flex items-baseline justify-between gap-2 mb-1.5 px-0.5">
              <div className="flex items-baseline gap-2" style={{ minWidth: 0 }}>
                <span style={{ color: COLOR.ink, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 13 }}>
                  {g.block} 座 · {g.wall}
                </span>
                <span style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, fontSize: 11 }}>
                  {(WING_META[g.wing] || { label: "" }).label}
                </span>
              </div>
              <span className="flex-shrink-0" style={{ color: COLOR.green, fontFamily: FONT_BODY, fontSize: 11, fontWeight: 700 }}>
                空 {g.items.length}
              </span>
            </div>
            <div className="space-y-2">
              {g.items.map((r) => {
                const sel = isSelected(r);
                return (
                  <Card key={keyOf(r)} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div className="flex-1" onClick={() => go("calculator", r, null, "niche")} style={{ cursor: "pointer" }}>
                      <span style={{ fontFamily: FONT_DISPLAY, color: COLOR.ink, fontSize: 15, fontWeight: 700 }}>{r.wall}-{r.code}</span>
                      {r.unit && <UnitPill unit={r.unit} />}
                      <div style={{ color: COLOR.inkSoft, fontSize: 12, fontFamily: FONT_BODY, marginTop: 2 }}>
                        {r.block} 座 · Hall {r.hallcode} · Level {r.level}
                      </div>
                    </div>
                    <StatusPill status="available" />
                    <button
                      onClick={() => toggleSelect(r)}
                      className="w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0"
                      style={{ border: `1.5px solid ${sel ? COLOR.gold : COLOR.line}`, background: sel ? COLOR.gold : "transparent" }}
                    >
                      {sel && <CheckCircle2 size={15} color="#161512" />}
                    </button>
                  </Card>
                );
              })}
            </div>
          </div>
        ))}
      </div>
      {results.length > 0 && (
        <p className="mt-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
          点卡片本身可直接带入计算器算单个福位的价钱
        </p>
      )}

      {selected.length > 0 && (
        <div className="fixed bottom-16 left-0 right-0 px-4 z-30">
          <div className="rounded-2xl px-4 py-3 flex items-center justify-between" style={{ background: COLOR.gold, boxShadow: "0 4px 20px rgba(0,0,0,0.4)" }}>
            <span style={{ color: "#161512", fontFamily: FONT_BODY, fontWeight: 700, fontSize: 13 }}>已选 {selected.length} 个福位</span>
            <div className="flex gap-2">
              <button onClick={() => setSelected([])} style={{ color: "#161512", fontFamily: FONT_BODY, fontSize: 12, fontWeight: 600, padding: "6px 10px" }}>清空</button>
              <button onClick={() => go("calculator", null, selected, "niche")} className="rounded-lg px-3 py-1.5" style={{ background: "#161512", color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12.5 }}>
                生成组合报价单
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================ PRICE CALCULATOR =================================== */
function MultiQuoteView({ items }) {
  const [doubles, setDoubles] = useState(items.map(() => true));
  const [showQuote, setShowQuote] = useState(false);

  const rows = items.map((it, i) => {
    const isDouble = doubles[i];
    const priceInfo = it.hallcode && it.side && it.level ? lookupPrice(it.block, it.hallcode, it.side, it.level) : null;
    // Actual Price is for reference only; all math runs off Promo Price.
    const actualPrice = priceInfo ? (isDouble ? priceInfo.doubleActual : priceInfo.singleActual) : null;
    const basePrice = priceInfo ? (isDouble ? priceInfo.doublePromo : priceInfo.singlePromo) : null;
    const eligible = REBATE_ELIGIBLE_BLOCKS.includes(it.block);
    const rebate40 = basePrice != null && eligible ? getRebate(basePrice, isDouble, "40") : 0;
    const net40 = basePrice != null ? basePrice - rebate40 : null;
    const rebateFP = basePrice != null && eligible ? getRebate(basePrice, isDouble, "FP") : 0;
    const netFP = basePrice != null ? basePrice - rebateFP : null;
    const urn = getUrnGift(isDouble);
    return { ...it, isDouble, actualPrice, basePrice, rebate40, net40, rebateFP, netFP, urn };
  });

  const validRows = rows.filter((r) => r.basePrice != null);
  const totalActual = validRows.reduce((a, r) => a + r.basePrice, 0);
  const total40Net = validRows.reduce((a, r) => a + (r.net40 || 0), 0);
  const totalFPNet = validRows.reduce((a, r) => a + (r.netFP || 0), 0);
  const totalUrnUnits = validRows.reduce((a, r) => a + r.urn.units, 0);
  const totalUrnValue = validRows.reduce((a, r) => a + r.urn.value, 0);
  const combinedPlan = total40Net > 0 ? computeInstallment(total40Net) : null;

  return (
    <div className="px-4 pt-4 pb-24">
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 组合报价:{items.length} 个福位一起算,头期/供期按合计净价计算
      </div>

      <div className="space-y-2 mb-4">
        {rows.map((r, i) => (
          <Card key={i}>
            <div className="flex items-center justify-between mb-1">
              <span style={{ fontFamily: FONT_DISPLAY, color: COLOR.ink, fontSize: 14, fontWeight: 700 }}>{r.block} 座 · {r.code}</span>
              <div className="flex gap-1">
                <button onClick={() => setDoubles((d) => d.map((v, idx) => (idx === i ? true : v)))}
                  className="text-[10px] px-2 py-1 rounded-full" style={{ background: r.isDouble ? COLOR.gold : COLOR.panel2, color: r.isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>双人</button>
                <button onClick={() => setDoubles((d) => d.map((v, idx) => (idx === i ? false : v)))}
                  className="text-[10px] px-2 py-1 rounded-full" style={{ background: !r.isDouble ? COLOR.gold : COLOR.panel2, color: !r.isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>单人</button>
              </div>
            </div>
            <div style={{ color: COLOR.inkSoft, fontSize: 11.5, fontFamily: FONT_BODY, marginBottom: 4 }}>
              {r.hallcode ? `Hall ${r.hallcode}` : "位置未精确标注"} · Level {r.level}
            </div>
            {r.basePrice != null ? (
              <Row label="促销价 · 40%净价" value={`${money(r.basePrice)} → ${money(r.net40)}`} bold />
            ) : (
              <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 12 }}>价格资料库里没有这个组合,请跟主管确认</p>
            )}
          </Card>
        ))}
      </div>

      {combinedPlan && (
        <Card style={{ border: `1px solid ${COLOR.gold}55`, marginBottom: 12 }}>
          <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 A · 分期付款(合计,标准 40% 头期)</div>
          <Row label="促销价合计 Total Promo" value={money(totalActual)} />
          <Row label="净价合计 Total Net (40%)" value={money(total40Net)} bold />
          <Row label="头期 Down Payment" value={money(combinedPlan.downPayment)} bold accent />
          <Row label="供期 Tenure" value={`${combinedPlan.tenure} 个月`} />
          <Row label="每月供款 Monthly" value={money(combinedPlan.monthly) + " / 月"} bold />
        </Card>
      )}

      <Card style={{ border: `1px solid ${COLOR.green}55`, marginBottom: 12 }}>
        <div style={{ color: COLOR.green, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 B · 全额付款(合计 FP)</div>
        <Row label="全款净价合计 Total Net Cash" value={money(totalFPNet)} bold accent />
        <Row label="附送翡翠水晶琉璃甕合计" value={`${totalUrnUnits} 个 (价值 ${money(totalUrnValue)})`} bold />
      </Card>

      <Btn onClick={() => setShowQuote(true)} className="w-full mt-2" variant="ghost">生成组合报价单预览</Btn>

      {showQuote && (
        <Card style={{ marginTop: 12, background: "#fff" }}>
          <div className="flex items-center gap-2 mb-3">
            <AlphaMark size={22} />
            <span style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, color: "#141414" }}>甲板山庄 Jiangnan Villa — 组合报价单</span>
          </div>
          <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: "#333", lineHeight: 1.8 }}>
            {rows.map((r, i) => (
              <div key={i} className="mb-1">
                {i + 1}. {r.block} 座 {r.hallcode || ""} {r.code} · Level {r.level} · {r.isDouble ? "双人" : "单人"} · {r.basePrice != null ? money(r.basePrice) : "价格待确认"}
              </div>
            ))}
            {combinedPlan && (
              <>
                <div className="mt-2"><b>— 方案 A 分期 40%(合计)—</b></div>
                <div>净价合计: {money(total40Net)} · 头期: {money(combinedPlan.downPayment)} · 供期: {combinedPlan.tenure} 个月 · 月供: {money(combinedPlan.monthly)}/月</div>
              </>
            )}
            <div className="mt-2"><b>— 方案 B 全额付款(合计)—</b></div>
            <div>全款净价合计: {money(totalFPNet)} · 附送翡翠水晶琉璃甕 {totalUrnUnits} 个</div>
            <div className="mt-2 text-[11px]" style={{ color: "#888" }}>促销有效期至 {fmtDate(CURRENT_PROMO.end)},价格与促销以公司最新公布为准。</div>
          </div>
        </Card>
      )}
    </div>
  );
}

function CalculatorScreen({ prefill, multiItems, mode, setMode }) {
  return (
    <div>
      <div className="px-4 pt-3 flex gap-2">
        <button onClick={() => setMode("niche")} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: mode === "niche" ? COLOR.gold : COLOR.panel2, color: mode === "niche" ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          骨灰位 Niche
        </button>
        <button onClick={() => setMode("burial")} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: mode === "burial" ? COLOR.gold : COLOR.panel2, color: mode === "burial" ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          土葬 Burial Plot
        </button>
      </div>
      {mode === "niche"
        ? (multiItems && multiItems.length > 0 ? <MultiQuoteView items={multiItems} /> : <SingleQuoteView prefill={prefill} />)
        : <BurialPlotView prefill={prefill} />}
    </div>
  );
}

function SingleQuoteView({ prefill }) {
  const [code, setCode] = useState(prefill?.code || "");
  const [block, setBlock] = useState(prefill?.block || "A");
  const [hallcode, setHallcode] = useState(prefill?.hallcode || "");
  const [side, setSide] = useState(prefill?.side || "");
  const [level, setLevel] = useState(prefill?.level || "");
  // The sheets say whether a niche is single or double, so when one is opened from the
  // grid or a search result, start on the right one instead of the old always-double
  // default -- picking double for a single niche quotes a price that isn't on offer.
  // Still switchable: if the sheet and the office ever disagree, the agent wins.
  const [isDouble, setIsDouble] = useState(prefill?.unit ? prefill.unit === "D" : true);
  const [showQuote, setShowQuote] = useState(false);

  // Skip auto-fill on initial mount if a prefill already fully specified the lot
  // (fixes bug: typing-based lookup was overwriting the prefill hall with the
  // first duplicate-code match elsewhere in the same block, e.g. Block L codes
  // that repeat across multiple Halls).
  const skippedPrefillAutoFill = useRef(false);
  const [ambiguousCode, setAmbiguousCode] = useState(false);

  useEffect(() => {
    if (!skippedPrefillAutoFill.current && prefill?.hallcode && code === prefill.code) {
      skippedPrefillAutoFill.current = true;
      return;
    }
    skippedPrefillAutoFill.current = true;

    if (!code.trim()) { setAmbiguousCode(false); return; }
    const matches = AVAIL.filter((r) => r.code.toLowerCase() === code.trim().toLowerCase() && (!block || r.block === block));
    setAmbiguousCode(matches.length > 1);
    const hit = matches[0];
    if (hit) {
      setBlock(hit.block); setHallcode(hit.hallcode); setSide(hit.side); setLevel(hit.level);
      // Typing a code should land on the same single/double as clicking one would.
      if (hit.unit) setIsDouble(hit.unit === "D");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code]);

  const hallOptions = Object.keys(HALL_GROUP[block] || {});
  useEffect(() => {
    if (!hallOptions.includes(hallcode)) { setHallcode(hallOptions[0] || ""); setSide(""); setLevel(""); }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [block]);

  const priceInfo = hallcode && side && level ? lookupPrice(block, hallcode, side, level) : null;
  // Actual Price is shown for reference only. Every calculation from here on
  // (rebate tier, net price, down payment, installment) always runs off the
  // Promo Price column in the price list, per company policy.
  const actualPrice = priceInfo ? (isDouble ? priceInfo.doubleActual : priceInfo.singleActual) : null;
  const basePrice = priceInfo ? (isDouble ? priceInfo.doublePromo : priceInfo.singlePromo) : null;

  const eligible = REBATE_ELIGIBLE_BLOCKS.includes(block);
  const rebate40 = basePrice != null && eligible ? getRebate(basePrice, isDouble, "40") : 0;
  const netPrice40 = basePrice != null ? basePrice - rebate40 : null;
  const plan = netPrice40 != null ? computeInstallment(netPrice40) : null;

  const rebateFP = basePrice != null && eligible ? getRebate(basePrice, isDouble, "FP") : 0;
  const netPriceFP = basePrice != null ? basePrice - rebateFP : null;
  const urnGift = getUrnGift(isDouble);

  return (
    <div className="px-4 pt-4 pb-24">
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 促销:{CURRENT_PROMO.name}({fmtDate(CURRENT_PROMO.start)}–{fmtDate(CURRENT_PROMO.end)}),头期固定按 40% 算
      </div>

      <TextInput placeholder="输入福位编号自动带入 (可选)" value={code} onChange={(e) => setCode(e.target.value)} className="mb-1" />
      {ambiguousCode && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 11.5, marginTop: 2, marginBottom: 10 }}>
          ⚠️ 这个编号在这个 Block 里出现在多个 Hall,系统按顺序选了其中一个,请手动核对/切换正确的 Hall
        </p>
      )}
      {!ambiguousCode && <div className="mb-3" />}

      <div className="grid grid-cols-2 gap-2 mb-3">
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Block</div>
          <Select value={block} onChange={(e) => setBlock(e.target.value)}>
            {BLOCKS.map((b) => <option key={b} value={b}>{b} 座</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Hall</div>
          <Select value={hallcode} onChange={(e) => { setHallcode(e.target.value); setSide(""); }}>
            <option value="">选择</option>
            {hallOptions.map((h) => <option key={h} value={h}>{h}</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>朝向 Side</div>
          <Select value={side} onChange={(e) => setSide(e.target.value)}>
            <option value="">选择</option>
            <option value="RL">Right / Left</option>
            <option value="F">Frontage</option>
            <option value="SEC">Section (L 座专用)</option>
            <option value="S">Side (N 座专用)</option>
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>楼层 Level</div>
          <TextInput placeholder="e.g. 10, 3A, 08-138" value={level} onChange={(e) => setLevel(e.target.value)} />
        </div>
      </div>

      <div className="flex gap-2 mb-4">
        <button onClick={() => setIsDouble(true)} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: isDouble ? COLOR.gold : COLOR.panel2, color: isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          双人 Double
        </button>
        <button onClick={() => setIsDouble(false)} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: !isDouble ? COLOR.gold : COLOR.panel2, color: !isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          单人 Single
        </button>
      </div>

      {hallcode && side && level && !priceInfo && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 13, lineHeight: 1.7 }}>
          {explainMissingPrice(block, hallcode, side, level)}
        </p>
      )}

      {basePrice != null && (
        <>
          <Card style={{ marginTop: 4, border: `1px solid ${COLOR.gold}55` }}>
            <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
              {block} 座 {hallcode} · {side === "F" ? "Frontage" : side === "SEC" ? "Section" : side === "S" ? "Side" : "Right/Left"} · Level {level} · {isDouble ? "双人" : "单人"}
            </div>
            <Row label="原价 Actual Price" value={money(actualPrice)} />
            <Row label="促销价 Promo Price(以此价格计算)" value={money(basePrice)} bold accent />
          </Card>

          <div className="mt-3">
            <MiniFloorPlan block={block} side={side} hallcode={hallcode} />
          </div>

          {plan && (
            <Card style={{ marginTop: 12, border: `1px solid ${COLOR.gold}55` }}>
              <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 A · 分期付款(标准 40% 头期)</div>
              <Row label={eligible ? "促销现金回扣 Cash Rebate (40%)" : "此 Block 不适用现金回扣"} value={rebate40 ? "-" + money(rebate40) : "—"} />
              <Row label="净价 Net Price" value={money(netPrice40)} bold />
              <Row label="头期 Down Payment(整数月供后补回)" value={money(plan.downPayment)} bold accent />
              <Row label="供期 Tenure" value={`${plan.tenure} 个月`} />
              <Row label="每月供款 Monthly" value={money(plan.monthly) + " / 月"} bold />
              <div className="mt-2 pt-2 text-[11px]" style={{ borderTop: `1px solid ${COLOR.line}`, color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
                供期按净价定:低于 RM10,000 = 18 个月;RM10,000–20,000 = 24 个月;高于 RM20,000 = 36 个月
              </div>
            </Card>
          )}

          {netPriceFP != null && (
            <Card style={{ marginTop: 12, border: `1px solid ${COLOR.green}55` }}>
              <div style={{ color: COLOR.green, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 B · 全额付款 Full Payment (FP)</div>
              <Row label={eligible ? "促销现金回扣 Cash Rebate (FP)" : "此 Block 不适用现金回扣"} value={rebateFP ? "-" + money(rebateFP) : "—"} />
              <Row label="全款净价 Net Cash Price" value={money(netPriceFP)} bold accent />
              <Row label="附送翡翠水晶琉璃甕 Complimentary Urn" value={`${urnGift.units} 个 (价值 ${money(urnGift.value)})`} bold />
              <div className="mt-2 pt-2 text-[11px]" style={{ borderTop: `1px solid ${COLOR.line}`, color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
                单人送 1 个,双人送 2 个,每个价值 RM1,688。只限全额付款的 Pre-need / Immigration 个案。
              </div>
            </Card>
          )}

          <Btn onClick={() => setShowQuote(true)} className="w-full mt-4" variant="ghost">生成报价单预览 Generate Quotation</Btn>

          {showQuote && (
            <Card style={{ marginTop: 12, background: "#fff" }}>
              <div className="flex items-center gap-2 mb-3">
                <AlphaMark size={22} />
                <span style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, color: "#141414" }}>甲板山庄 Jiangnan Villa — Quotation</span>
              </div>
              <div style={{ fontFamily: FONT_BODY, fontSize: 12.5, color: "#333", lineHeight: 1.9 }}>
                <div><b>福位 Niche:</b> {block} 座 {hallcode} {code && `(${code})`} · Level {level} · {isDouble ? "双人 Double" : "单人 Single"}</div>
                <div><b>原价 Actual Price:</b> {money(actualPrice)}</div>
                <div><b>促销价 Promo Price(计算基础):</b> {money(basePrice)}</div>
                {plan && (
                  <>
                    <div className="mt-1"><b>— 方案 A 分期 40% —</b></div>
                    <div>现金回扣: {rebate40 ? money(rebate40) : "不适用"} · 净价: {money(netPrice40)}</div>
                    <div>头期: {money(plan.downPayment)} · 供期: {plan.tenure} 个月 · 月供: {money(plan.monthly)}/月</div>
                  </>
                )}
                <div className="mt-1"><b>— 方案 B 全额付款 FP —</b></div>
                <div>现金回扣: {rebateFP ? money(rebateFP) : "不适用"} · 全款净价: {money(netPriceFP)}</div>
                <div>附送翡翠水晶琉璃甕 {urnGift.units} 个(价值 {money(urnGift.value)})</div>
                <div className="mt-2 text-[11px]" style={{ color: "#888" }}>促销有效期至 {fmtDate(CURRENT_PROMO.end)},价格与促销以公司最新公布为准。</div>
              </div>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

function BurialPlotView({ prefill }) {
  const prefillZone = prefill?.zoneKey && BURIAL_ZONES.some((z) => z.key === prefill.zoneKey) ? prefill.zoneKey : null;
  const [zoneKey, setZoneKey] = useState(prefillZone || BURIAL_ZONES[0].key);
  const [categoryKey, setCategoryKey] = useState((BURIAL_ZONES.find((z) => z.key === (prefillZone || BURIAL_ZONES[0].key)) || BURIAL_ZONES[0]).categories[0].key);
  const [tierKey, setTierKey] = useState("");

  const zone = BURIAL_ZONES.find((z) => z.key === zoneKey) || BURIAL_ZONES[0];
  const category = zone.categories.find((c) => c.key === categoryKey) || zone.categories[0];
  const tiers = burialRebateTiers(zone);
  const activeTierKey = tiers.includes(tierKey) ? tierKey : tiers[0];

  const result = computeBurialTier(zone, category.promo, activeTierKey);

  const handleZoneChange = (key) => {
    const nextZone = BURIAL_ZONES.find((z) => z.key === key) || BURIAL_ZONES[0];
    setZoneKey(key);
    setCategoryKey(nextZone.categories[0].key);
    setTierKey(burialRebateTiers(nextZone)[0]);
  };

  return (
    <div className="px-4 pt-4 pb-24">
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 土葬各 Zone 价格来自公司价格表;计算一律以「促销价 Promo Price」为准,原价只作参考
      </div>

      {prefill?.code && (
        <p style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontSize: 11.5, marginBottom: 10 }}>
          从空置图带入柱位:{prefill.code} — 系统不知道这个柱位属于哪个价格类别,请手动核对下面「类别」是否正确
        </p>
      )}

      <div className="grid grid-cols-2 gap-2 mb-3">
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Zone</div>
          <Select value={zone.key} onChange={(e) => handleZoneChange(e.target.value)}>
            {BURIAL_ZONES.map((z) => <option key={z.key} value={z.key}>{z.label}</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>类别 Category</div>
          <Select value={category.key} onChange={(e) => setCategoryKey(e.target.value)}>
            {zone.categories.map((c) => <option key={c.key} value={c.key}>{c.label}</option>)}
          </Select>
        </div>
      </div>

      {category.note && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 11.5, marginBottom: 10 }}>⚠️ {category.note}</p>
      )}

      <Card style={{ marginTop: 4, border: `1px solid ${COLOR.gold}55` }}>
        <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
          {zone.label} · {category.label}
        </div>
        <Row label="面积 Size" value={zone.size} />
        <Row label="用位 No. of Interment" value={`${zone.pax} 位`} />
        <Row label="原价 Actual Price" value={money(category.actual)} />
        <Row label="促销价 Promo Price(以此价格计算)" value={money(category.promo)} bold accent />
        <Row label="价格生效日 WEF" value={zone.wef} />
      </Card>

      <div className="flex gap-2 mt-3 mb-1 flex-wrap">
        {tiers.map((t) => (
          <button key={t} onClick={() => setTierKey(t)} className="rounded-xl px-3 py-2 text-sm"
            style={{ background: activeTierKey === t ? COLOR.gold : COLOR.panel2, color: activeTierKey === t ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
            {BURIAL_TIER_LABEL[t] || t}
          </button>
        ))}
      </div>

      <Card style={{ marginTop: 8, border: `1px solid ${result.isFP ? COLOR.green : COLOR.gold}55` }}>
        <div style={{ color: result.isFP ? COLOR.green : COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
          {result.isFP ? "全额付款 Full Payment" : `${BURIAL_TIER_LABEL[result.tierKey] || result.tierKey} 分期方案`}
        </div>
        <Row label={zone.rebate ? "促销现金回扣 Cash Rebate" : "此 Zone 暂无现金回扣促销资料"} value={result.rebate ? "-" + money(result.rebate) : "—"} />
        <Row label="净价 Net Price" value={money(result.netPrice)} bold />
        {result.isFP ? (
          <Row label="全款金额 Full Payment Amount" value={money(result.downPayment)} bold accent />
        ) : (
          <>
            <Row label="头期 Down Payment" value={money(result.downPayment)} bold accent />
            <Row label="供期 Tenure" value={`${result.tenure} 个月`} />
            <Row label="每月供款 Monthly" value={money(result.monthly) + " / 月"} bold />
          </>
        )}
      </Card>

      <div className="mt-3 text-[11px]" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, lineHeight: 1.7 }}>
        Booking fee RM500 起(Zone IZ 为 RM1,000)· Sheng-Ji 附加费一般 RM1,200/次(Zone DA 为 RM650)。价格与促销以公司最新公布为准。
        此计算器不含逐格查询——各 Zone 楼层图上实际哪个柱位还空置,请与主管确认后再报价。
      </div>
    </div>
  );
}

